// Generated by circuits/rebuild.py; one topology per leaf.
use rand::{Rng, rngs::StdRng};

fn pick(rng: &mut StdRng, values: &[f64]) -> f64 {
    values[rng.random_range(0..values.len())]
}

fn preferred(rng: &mut StdRng, low: i32, high: i32) -> f64 {
    pick(
        rng,
        &[1.0, 1.2, 1.5, 1.8, 2.2, 2.7, 3.3, 3.9, 4.7, 5.6, 6.8, 8.2],
    ) * 10.0_f64.powi(rng.random_range(low..=high))
}

fn number(value: f64) -> String {
    let scientific = format!("{value:.3e}");
    let (mantissa, exponent) = scientific.split_once('e').unwrap();
    let mantissa = mantissa.trim_end_matches('0').trim_end_matches('.');
    let exponent: i32 = exponent.parse().unwrap();
    if (-2..=2).contains(&exponent) {
        let decimal = format!("{value:.precision$}", precision = (3 - exponent) as usize);
        decimal
            .trim_end_matches('0')
            .trim_end_matches('.')
            .to_owned()
    } else {
        format!("{mantissa}e{exponent}")
    }
}

fn part(name: &str, from: &str, to: &str, value: f64) -> String {
    format!("{name} {from} {to} {}", number(value))
}

pub fn generate(rng: &mut StdRng) -> String {
    let r = preferred(rng, 3, 4);
    let rf = preferred(rng, 3, 4);
    let a = pick(rng, &[1e3, 1e4, 1e5, 1e6]);
    let r2 = r * pick(rng, &[0.5, 1.0, 2.0, 5.0]);
    let mut lines = vec![
        "Summing VCVS amplifier".to_owned(),
        "V1 in 0 DC 0.1".to_owned(),
        part("R1", "in", "inv", r),
        part("Rf", "inv", "out", rf),
        format!("E1 out 0 0 inv {}", number(a)),
    ];
    lines.extend(["V2 in2 0 DC -0.05".to_owned(), part("R2", "in2", "inv", r2)]);
    lines.extend([
        ".op".to_owned(),
        ".dc V1 -0.1 0.1 0.005".to_owned(),
        ".print dc v(in) v(out)".to_owned(),
        ".end".to_owned(),
    ]);
    lines.join("\n")
}

#[cfg(test)]
mod validate {
    include!("../../../validate.rs");
}

#[cfg(test)]
mod tests {
    use super::*;
    use rand::SeedableRng;

    #[test]
    fn independent_nodal_analysis_matches_topology() {
        let mut rng = StdRng::seed_from_u64(47);
        for _ in 0..200 {
            validate::verify(&generate(&mut rng), "summing");
        }
    }
}
